import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.BpFM782D.js";const u=JSON.parse('{"title":"vercel-composition-patterns","description":"","frontmatter":{},"headers":[],"relativePath":"skills/vercel-composition-patterns.md","filePath":"skills/vercel-composition-patterns.md"}'),d={name:"skills/vercel-composition-patterns.md"};function i(l,t,c,n,s,h){return a(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="vercel-composition-patterns" tabindex="-1">vercel-composition-patterns <a class="header-anchor" href="#vercel-composition-patterns" aria-label="Permalink to &quot;vercel-composition-patterns&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>vercel-composition-patterns</td></tr><tr><td>說明</td><td>Vercel 組合模式。Server Components、Client Components 的組合策略與最佳實踐。</td></tr><tr><td>來源目錄</td><td><code>skills/vercel-composition-patterns/</code></td></tr></tbody></table><hr><h1 id="react-組合模式" tabindex="-1">React 組合模式 <a class="header-anchor" href="#react-組合模式" aria-label="Permalink to &quot;React 組合模式&quot;">​</a></h1><p>用於建立靈活、可維護的 React 元件的組合模式。透過使用複合元件、提升狀態與組合內部，避免布林 prop 泛濫。這些模式能讓程式碼庫在擴展時對人類與 AI agent 都更易於維護。</p><h2 id="適用時機" tabindex="-1">適用時機 <a class="header-anchor" href="#適用時機" aria-label="Permalink to &quot;適用時機&quot;">​</a></h2><p>在以下情況請參考這些指南：</p><ul><li>重構有許多布林 prop 的元件</li><li>建立可重用的元件函式庫</li><li>設計靈活的元件 API</li><li>審查元件架構</li><li>使用複合元件或 context provider</li></ul><h2 id="規則類別-依優先順序" tabindex="-1">規則類別（依優先順序） <a class="header-anchor" href="#規則類別-依優先順序" aria-label="Permalink to &quot;規則類別（依優先順序）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>優先順序</th><th>類別</th><th>影響程度</th><th>前綴</th></tr></thead><tbody><tr><td>1</td><td>元件架構</td><td>HIGH</td><td><code>architecture-</code></td></tr><tr><td>2</td><td>狀態管理</td><td>MEDIUM</td><td><code>state-</code></td></tr><tr><td>3</td><td>實作模式</td><td>MEDIUM</td><td><code>patterns-</code></td></tr><tr><td>4</td><td>React 19 API</td><td>MEDIUM</td><td><code>react19-</code></td></tr></tbody></table><h2 id="快速參考" tabindex="-1">快速參考 <a class="header-anchor" href="#快速參考" aria-label="Permalink to &quot;快速參考&quot;">​</a></h2><h3 id="_1-元件架構-high" tabindex="-1">1. 元件架構（HIGH） <a class="header-anchor" href="#_1-元件架構-high" aria-label="Permalink to &quot;1. 元件架構（HIGH）&quot;">​</a></h3><ul><li><code>architecture-avoid-boolean-props</code> - 不要用布林 prop 自訂行為；改用組合</li><li><code>architecture-compound-components</code> - 以共享 context 建構複雜元件</li></ul><h3 id="_2-狀態管理-medium" tabindex="-1">2. 狀態管理（MEDIUM） <a class="header-anchor" href="#_2-狀態管理-medium" aria-label="Permalink to &quot;2. 狀態管理（MEDIUM）&quot;">​</a></h3><ul><li><code>state-decouple-implementation</code> - Provider 是唯一知道如何管理狀態的地方</li><li><code>state-context-interface</code> - 定義含有 state、actions、meta 的通用介面以進行相依性注入</li><li><code>state-lift-state</code> - 將狀態移入 provider 元件以供兄弟元件存取</li></ul><h3 id="_3-實作模式-medium" tabindex="-1">3. 實作模式（MEDIUM） <a class="header-anchor" href="#_3-實作模式-medium" aria-label="Permalink to &quot;3. 實作模式（MEDIUM）&quot;">​</a></h3><ul><li><code>patterns-explicit-variants</code> - 建立明確的變體元件，而非布林模式</li><li><code>patterns-children-over-render-props</code> - 使用 children 進行組合，而非 renderX prop</li></ul><h3 id="_4-react-19-api-medium" tabindex="-1">4. React 19 API（MEDIUM） <a class="header-anchor" href="#_4-react-19-api-medium" aria-label="Permalink to &quot;4. React 19 API（MEDIUM）&quot;">​</a></h3><blockquote><p><strong>⚠️ 僅限 React 19+。</strong> 若使用 React 18 或更早版本，請跳過此區段。</p></blockquote><ul><li><code>react19-no-forwardref</code> - 不要使用 <code>forwardRef</code>；使用 <code>use()</code> 而非 <code>useContext()</code></li></ul><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><p>閱讀各個規則檔案以獲得詳細說明與程式碼範例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rules/architecture-avoid-boolean-props.md</span></span>
<span class="line"><span>rules/state-context-interface.md</span></span></code></pre></div><p>每個規則檔案包含：</p><ul><li>為何重要的簡短說明</li><li>含說明的錯誤程式碼範例</li><li>含說明的正確程式碼範例</li><li>額外情境與參考資料</li></ul><h2 id="完整編譯文件" tabindex="-1">完整編譯文件 <a class="header-anchor" href="#完整編譯文件" aria-label="Permalink to &quot;完整編譯文件&quot;">​</a></h2><p>包含所有規則的完整指南：<code>AGENTS.md</code></p>`,27)])])}const m=e(d,[["render",i]]);export{u as __pageData,m as default};
